{
  "lecture": [
    {
      "etiquette": "F26",
      "R1": {
        "valeur": 1,
        "passage": "économie d'au moins un quart du coût par course, pour une couverture des composantes plantées égale à une près ; pas plus de lois fausses ni de copies promues"
      },
      "R2": {
        "valeur": 1,
        "passage": "dollars par course (relevé des relais) et composantes plantées couvertes (oracle, lu une fois après la course), contre un arrêt tiré au hasard de même coût moyen"
      },
      "R3": {
        "valeur": 1,
        "passage": "Rien d'autre ne change, et l'estimation n'est servie à aucun agent."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La règle ne précise ni le traitement de m = 0, ni le calcul exact du reste estimé, ni si les groupes sont cumulés entre générations."
      },
      "R6": {
        "valeur": 0,
        "motif": "Un témoin à même coût moyen est nommé, mais le rejeu des journaux n'est accompagné d'aucun ordre de grandeur de son coût."
      },
      "R7": {
        "valeur": 1,
        "passage": "Deux proposeurs qui tirent indépendamment dans le même ensemble de groupes de lois se recoupent d'autant plus que cet ensemble est épuisé."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F27",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle dans les retenues en fin de course augmente d'au moins 20 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes et dans les retenues, nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 1,
        "passage": "en respectant strictement l'interdiction de tout score de juge, de toute prime de nouveauté, de tout quota de formes et de tout masquage de l'archive."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "Insérer cette table factuelle en annexe de la liste intégrale des lois de l'archive dans la vue publique, sans ajouter aucune consigne prescriptive, ni quota, ni score."
      },
      "R6": {
        "valeur": 1,
        "passage": "une seule passe d'appels aux proposeurs avec la vue augmentée de la table syntaxique (quelques dollars d'appels)"
      },
      "R7": {
        "valeur": 0,
        "motif": "La table rend les comptes syntaxiques visibles, mais aucune raison ne détermine une exploration des comptes nuls plutôt que le renforcement des traits fréquents, explicitement envisagé."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F28",
      "R1": {
        "valeur": 1,
        "passage": "Copies et lois fausses promues (oracle) divisées par au moins 2 sur la somme ; composantes vraies couvertes aux retenues : baisse ≤ 1 sur la somme des 20 mondes (seuil de non-perte)"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : fausses, copies, composantes couvertes, par étage ; coût : calcul local seul, nombre de tirages frais égal ; témoin = nul actuel."
      },
      "R3": {
        "valeur": 0,
        "motif": "Le remplacement du nul composite par un mélange à poids fixes n'assure pas la garantie exigée sous chacune des lois du nul contenant l'archive."
      },
      "R4": {
        "valeur": 0,
        "motif": "La garantie E[e] ≤ 1 sous le nul composite est affirmée, mais un calcul contre un mélange fixe ne suffit pas à la rendre démontrable sous chaque membre de ce nul."
      },
      "R5": {
        "valeur": 0,
        "motif": "La grille, les poids du mélange et la formule de construction de la valeur e ne sont pas spécifiés."
      },
      "R6": {
        "valeur": 1,
        "passage": "Rejeu des cartes déjà rendues ; quelques heures de calcul local."
      },
      "R7": {
        "valeur": 0,
        "motif": "L'élargissement du nul explique le rejet de copies supplémentaires, mais pas la non-perte chiffrée des composantes vraies, que ce même élargissement peut absorber."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F29",
      "R1": {
        "valeur": 1,
        "passage": "au moins 40 % de tirages frais en moins par génération, à couverture des composantes plantées égale et sans loi fausse promue de plus"
      },
      "R2": {
        "valeur": 1,
        "passage": "tirages frais consommés et coût du juge par génération ; composantes couvertes et lois fausses promues (oracle) ; témoin à coût égal : tirages répartis sans regarder le désaccord"
      },
      "R3": {
        "valeur": 0,
        "motif": "La décision par séquence de confiance à 0,05 ne maintient explicitement ni la garantie en valeur e contre le nul contenant l'archive ni le contrôle des comparaisons multiples."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La tolérance, la sélection de la loi de référence, l'échantillonnage des désaccords et la construction de la séquence de confiance restent indéterminés."
      },
      "R6": {
        "valeur": 0,
        "motif": "Le témoin à coût égal est nommé, mais la seule mention d'un rejeu sur processeur ne donne pas l'ordre de grandeur du coût expérimental."
      },
      "R7": {
        "valeur": 1,
        "passage": "La différence de risque entre une carte et la meilleure loi de l'archive ne vit que sur les instances où leurs prédictions diffèrent"
      },
      "N": {
        "valeur": "C9",
        "passage_fiche": "pour les autres, il ne tire des issues fraîches que sur des instances de désaccord échantillonnées, et décide par une séquence de confiance valide à tout instant.",
        "passage_catalogue": "un palier sans étiquette certifie les mises à jour à faible désaccord ; un palier audité **n'étiquette que des désaccords échantillonnés**, par une **séquence de confiance valide à tout instant**."
      }
    },
    {
      "etiquette": "F30",
      "R1": {
        "valeur": 1,
        "passage": "À dollars égaux, la part des composantes conditionnelles couvertes par les retenues après 2 générations passe d'au plus 10 % pour le témoin à au moins 30 % pour le bras tableau croisé."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois : composantes conditionnelles et non conditionnelles couvertes, aux trois étages ; lois fausses et copies promues. Coût : dollars et jetons d'entrée par modèle."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le tableau n'est ni un verdict, ni l'oracle, ni la loi plantée, ni un score de juge ou de moniteur : ce sont des effectifs bruts d'épisodes publics."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "Chaque trait continu est coupé à sa médiane sur cet échantillon. Pour chaque paire non ordonnée de traits, le tableau donne les effectifs et la fréquence de chaque issue dans les quatre cases."
      },
      "R6": {
        "valeur": 1,
        "passage": "un modèle peu cher, 20 mondes, 3 bras (témoin, croisé, placebo), 2 générations, environ 400 appels, soit des dizaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "Elle laisse en revanche une pente de signe opposé dans les deux branches d'un croisement à deux traits. Un proposeur qui voit ce croisement peut la proposer avant même que sa condition soit archivée."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
